import { Table, StringColumn, BooleanColumn } from '../../db'

export const sys_ui_annotation_type = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_truncate: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Form Annotation Type',
    name: 'sys_ui_annotation_type',
    schema: {
        style: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Style',
            maxLength: 1000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        omit_spacer: BooleanColumn({
            label: [
                {
                    hint: 'Omit the spacer preserving annotation height',
                    label: 'Omit spacer',
                    plural: 'Omit spacers',
                },
            ],
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Name',
            maxLength: 80,
        }),
    },
    textIndex: true,
})
